INSERT INTO public.intake_sessions (id, channel, customer_id, wa_contact_id, state, facts, pending_field, draft, escalation, job_id, provider, turn_count, created_at, updated_at) VALUES ('b38c1dd8-34ed-494c-b900-4dc307095b82', 'web', '98ac767b-19b3-465c-8ec5-052ebd27741c', NULL, 'published', '{"scope": {"value": "20 meter heg en 50 m2 gazon", "source": "customer"}, "budget": {"value": null, "source": "customer"}, "timing": {"value": "flexibel", "source": "customer"}, "problem": {"value": "Onze heg moet gesnoeid worden en het gazon verticuteren", "source": "customer"}, "category": {"value": "tuinonderhoud", "source": "ai_inferred"}, "postcode": {"value": "3521 KL", "source": "customer"}}', NULL, '{"title": "Tuinonderhoud: onze heg moet gesnoeid worden en het gazon verticuteren — Utrecht", "assumptions": ["Categorie is door AI ingeschat: “Tuinonderhoud”. Klopt dit niet? Laat het ons weten."], "description": "Klant zoekt een vakman voor tuinonderhoud in de regio Utrecht (3521).\n\nOmschrijving door de klant: Onze heg moet gesnoeid worden en het gazon verticuteren\n\n• Omvang (schatting klant): 20 meter heg en 50 m2 gazon\n• Gewenste planning: Flexibel / in overleg\n• Maximaal budget: geen maximum opgegeven\n\nMaten en hoeveelheden zijn schattingen van de klant. Controleer ter plaatse voordat je een definitieve prijs afgeeft."}', NULL, '273d6146-e832-47cb-8768-df96b2b1fc3d', 'rules', 5, '2026-11-16 09:56:09.355705+00', '2026-11-16 09:56:09.38242+00');
